import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda_bf16.h>
#include <cuda_runtime.h>

#define K 3
#define C_IN 3
#define C_OUT 32

__global__ void conv2d_bf16_kernel(
    const __nv_bfloat16* __restrict__ input,
    const __nv_bfloat16* __restrict__ weight,
    __nv_bfloat16* __restrict__ output,
    int N, int H, int W, int H_out, int W_out)
{
    __shared__ __nv_bfloat16 s_weight[C_OUT*C_IN*K*K];
    int tid = threadIdx.x;
    int wsize = C_OUT*C_IN*K*K;
    for (int i = tid; i < wsize; i += blockDim.x) {
        s_weight[i] = weight[i];
    }
    __syncthreads();

    int total = N * C_OUT * H_out * W_out;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int stride = blockDim.x * gridDim.x;
    for (; idx < total; idx += stride) {
        int w_out = idx % W_out;
        int h_out = (idx / W_out) % H_out;
        int c_out = (idx / (W_out*H_out)) % C_OUT;
        int n = idx / (W_out*H_out*C_OUT);

        float acc = 0.0f;
        const __nv_bfloat16* in_n = input + (long)n * C_IN*H*W;
        #pragma unroll
        for (int c_in = 0; c_in < C_IN; c_in++) {
            const __nv_bfloat16* in_c = in_n + (long)c_in*H*W;
            const __nv_bfloat16* w_c = s_weight + (c_out*C_IN + c_in)*K*K;
            #pragma unroll
            for (int kh = 0; kh < K; kh++) {
                int h_in = h_out + kh;
                const __nv_bfloat16* in_row = in_c + (long)h_in*W + w_out;
                #pragma unroll
                for (int kw = 0; kw < K; kw++) {
                    float in_val = __bfloat162float(in_row[kw]);
                    float w_val = __bfloat162float(w_c[kh*K+kw]);
                    acc += in_val * w_val;
                }
            }
        }
        output[idx] = __float2bfloat16(acc);
    }
}

torch::Tensor conv2d_bf16_forward(torch::Tensor input, torch::Tensor weight) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kBFloat16, "input must be bf16");
    TORCH_CHECK(weight.dtype() == torch::kBFloat16, "weight must be bf16");

    input = input.contiguous();
    weight = weight.contiguous();

    int N = input.size(0);
    int C_in = input.size(1);
    int H = input.size(2);
    int W = input.size(3);
    int C_out = weight.size(0);
    int Kh = weight.size(2);
    int Kw = weight.size(3);

    int H_out = H - Kh + 1;
    int W_out = W - Kw + 1;

    auto output = torch::empty({N, C_out, H_out, W_out}, input.options());

    int total = N * C_out * H_out * W_out;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;
    if (blocks > 65535) blocks = 65535;
    if (blocks < 1) blocks = 1;

    conv2d_bf16_kernel<<<blocks, threads>>>(
        reinterpret_cast<const __nv_bfloat16*>(input.data_ptr<at::BFloat16>()),
        reinterpret_cast<const __nv_bfloat16*>(weight.data_ptr<at::BFloat16>()),
        reinterpret_cast<__nv_bfloat16*>(output.data_ptr<at::BFloat16>()),
        N, H, W, H_out, W_out
    );

    return output;
}
"""

cpp_source = r"""
torch::Tensor conv2d_bf16_forward(torch::Tensor input, torch::Tensor weight);
"""

conv2d_module = load_inline(
    name="conv2d_bf16_module",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["conv2d_bf16_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        # Match nn.Conv2d default initialization semantics exactly by
        # constructing an actual nn.Conv2d and reusing its initialized weight.
        ref_conv = nn.Conv2d(3, 32, kernel_size=3, bias=False, dtype=torch.bfloat16)
        self.weight = nn.Parameter(ref_conv.weight.detach().clone())

    def forward(self, x):
        return conv2d_module.conv2d_bf16_forward(x, self.weight)

